{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.customer_acq_date_channel as WITH online_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, \'Shopify\' AS store, MIN(order_timestamp) AS online_acq FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1 ), offline_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, marketplace_mapped AS store, order_timestamp AS offline_acq FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' QUALIFY ROW_NUMBER() OVER (PARTITION BY \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) ORDER BY order_timestamp ASC) = 1 ), online_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(gross_sales) AS online_sales FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1 ), offline_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(selling_price) as offline_sales FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' group by 1 ), combined_acq AS ( SELECT phone_no, online_acq AS order_date, store FROM online_acq UNION ALL SELECT phone_no, offline_acq AS order_date, store FROM offline_acq ), final_check as ( SELECT phone_no, order_date::date AS first_order_date, store FROM combined_acq qualify row_number() over (partition by phone_no order by order_date asc) = 1 ) select a.*, ifnull(online_sales,0) as online_sales, ifnull(offline_sales,0) as offline_sales, case when ifnull(online_sales,0)>= ifnull(offline_sales,0) then \'Shopify\' else \'Stores\' end as customer_main_channel from final_check a left join online_sales b on a.phone_no = b.phone_no left join offline_sales c on a.phone_no = c.phone_no where length(a.phone_no) = 13 and a.phone_no not in (\'+911234567890\',\'+911234567891\',\'+910123456789\',\'+911111111111\',\'+912727272727\',\'+918888888888\',\'+919999999999\',\'+910000000000\',\'+912424242424\',\'+919909090909\') ; create or replace table snitch_db.maplemonk.retention_overall as ( WITH orders_union AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_timestamp::date AS order_date, SUM(gross_sales) AS sales, SUM(quantity) AS quantity, COUNT(DISTINCT combined_order_name) AS orders, \'Online\' AS order_store FROM snitch_db.maplemonk.fact_items_snitch GROUP BY 1,2 UNION ALL SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_date, SUM(selling_price) AS sales, SUM(suborder_quantity) AS quantity, COUNT(order_name) AS orders, \'Offline\' AS order_store FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE NOT LOWER(marketplace_mapped) LIKE \'%wh%\' GROUP BY 1,2 ), orders_clean AS ( SELECT phone_no, order_date, order_store, SUM(sales) AS sales, SUM(quantity) AS quantity, SUM(orders) AS orders FROM orders_union WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\',\'+911234567891\',\'+910123456789\',\'+911111111111\',\'+912727272727\', \'+918888888888\',\'+919999999999\',\'+910000000000\',\'+912424242424\',\'+919909090909\' ) GROUP BY 1,2,3 ), cohorts AS ( SELECT b.phone_no, b.first_order_date, DATE_TRUNC(\'month\', b.first_order_date) AS acq_month, CASE WHEN b.store = \'Shopify\' THEN \'Online\' ELSE \'Offline\' END AS acq_store FROM snitch_db.maplemonk.customer_acq_date_channel b WHERE b.first_order_date IS NOT NULL ), orders_with_month_diff AS ( SELECT c.phone_no, c.first_order_date, c.acq_month, c.acq_store, o.order_date, o.order_store, o.sales, o.quantity, o.orders, DATEDIFF(\'month\', c.first_order_date, o.order_date) AS month_diff FROM cohorts c JOIN orders_clean o ON c.phone_no = o.phone_no ), views AS ( SELECT \'overall_any_acq_any_repeat\' AS view_type, NULL AS acq_store_filter, NULL AS repeat_store_filter UNION ALL SELECT \'online_acq_overall\', \'Online\', NULL UNION ALL SELECT \'offline_acq_overall\', \'Offline\', NULL UNION ALL SELECT \'online_acq_online\', \'Online\', \'Online\' UNION ALL SELECT \'online_acq_offline\', \'Online\', \'Offline\' UNION ALL SELECT \'offline_acq_offline\', \'Offline\', \'Offline\' UNION ALL SELECT \'offline_acq_online\', \'Offline\', \'Online\' ), cohort_sizes AS ( SELECT v.view_type, c.acq_month, COUNT(DISTINCT c.phone_no) AS acq_customers FROM views v JOIN cohorts c ON (v.acq_store_filter IS NULL OR c.acq_store = v.acq_store_filter) GROUP BY 1,2 ), acq_metrics AS ( SELECT v.view_type, o.acq_month, SUM(CASE WHEN o.month_diff = 0 THEN o.sales END) AS acq_sales, SUM(CASE WHEN o.month_diff = 0 THEN o.quantity END) AS acq_quantity FROM views v JOIN orders_with_month_diff o ON (v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter) GROUP BY 1,2 ), repeat_metrics AS ( SELECT v.view_type, o.acq_month, COUNT(DISTINCT CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m1_customers, SUM(CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m1_sales, SUM(CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m1_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m3_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m3_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m3_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m6_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m6_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m6_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m12_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m12_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m12_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m18_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m18_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m18_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m24_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m24_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m24_quantity FROM views v JOIN orders_with_month_diff o ON (v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter) GROUP BY 1,2 ), final AS ( SELECT cs.view_type, cs.acq_month, cs.acq_customers, am.acq_sales, am.acq_quantity, COALESCE(rm.m1_customers,0) AS m1_customers, COALESCE(rm.m3_customers,0) AS m3_customers, COALESCE(rm.m6_customers,0) AS m6_customers, COALESCE(rm.m12_customers,0) AS m12_customers, COALESCE(rm.m18_customers,0) AS m18_customers, COALESCE(rm.m24_customers,0) AS m24_customers, COALESCE(rm.m1_sales,0) AS m1_sales, COALESCE(rm.m3_sales,0) AS m3_sales, COALESCE(rm.m6_sales,0) AS m6_sales, COALESCE(rm.m12_sales,0) AS m12_sales, COALESCE(rm.m18_sales,0) AS m18_sales, COALESCE(rm.m24_sales,0) AS m24_sales, COALESCE(rm.m1_quantity,0) AS m1_quantity, COALESCE(rm.m3_quantity,0) AS m3_quantity, COALESCE(rm.m6_quantity,0) AS m6_quantity, COALESCE(rm.m12_quantity,0) AS m12_quantity, COALESCE(rm.m18_quantity,0) AS m18_quantity, COALESCE(rm.m24_quantity,0) AS m24_quantity FROM cohort_sizes cs LEFT JOIN acq_metrics am ON cs.view_type = am.view_type AND cs.acq_month = am.acq_month LEFT JOIN repeat_metrics rm ON cs.view_type = rm.view_type AND cs.acq_month = rm.acq_month ) SELECT view_type, acq_month, acq_customers, acq_sales::int AS acq_sales, acq_quantity::int AS acq_quantity, DIV0(m1_customers, acq_customers) AS m1_customer_retention, DIV0(m3_customers, acq_customers) AS m3_customer_retention, DIV0(m6_customers, acq_customers) AS m6_customer_retention, DIV0(m12_customers, acq_customers) AS m12_customer_retention, DIV0(m18_customers, acq_customers) AS m18_customer_retention, DIV0(m24_customers, acq_customers) AS m24_customer_retention, DIV0(m1_sales, acq_sales) AS m1_sales_retention, DIV0(m3_sales, acq_sales) AS m3_sales_retention, DIV0(m6_sales, acq_sales) AS m6_sales_retention, DIV0(m12_sales, acq_sales) AS m12_sales_retention, DIV0(m18_sales, acq_sales) AS m18_sales_retention, DIV0(m24_sales, acq_sales) AS m24_sales_retention, DIV0(m1_quantity, acq_quantity) AS m1_quantity_retention, DIV0(m3_quantity, acq_quantity) AS m3_quantity_retention, DIV0(m6_quantity, acq_quantity) AS m6_quantity_retention, DIV0(m12_quantity, acq_quantity) AS m12_quantity_retention, DIV0(m18_quantity, acq_quantity) AS m18_quantity_retention, DIV0(m24_quantity, acq_quantity) AS m24_quantity_retention FROM final ORDER BY view_type, acq_month );",
                    "transaction": true
                }
            ) }}
